package com.johnny.hotel;import com.johnny.hotel.businessdate.*;import com.johnny.hotel.cashier.*;import com.johnny.hotel.cashier.CashierModels.*;import com.johnny.hotel.entity.*;import com.johnny.hotel.mapper.*;import com.johnny.hotel.pagination.*;import com.johnny.hotel.payment.*;import com.johnny.hotel.task.*;import org.junit.jupiter.api.*;import java.math.*;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class CashierCoreServiceTest{CashierMapper db;CashierAccess access;BusinessDateService dates;CashierPostingService posting;HotelTaskMapper tasks;TaskRecordMapper records;HotelTaskService taskService;PaymentCoreMapper tx;SysAuditLogMapper audits;CashierService service;Clock clock=Clock.fixed(Instant.parse("2026-09-24T02:00:00Z"),ZoneId.of("Asia/Shanghai"));
 @BeforeEach void init(){db=mock(CashierMapper.class);access=mock(CashierAccess.class);dates=mock(BusinessDateService.class);posting=mock(CashierPostingService.class);tasks=mock(HotelTaskMapper.class);records=mock(TaskRecordMapper.class);taskService=mock(HotelTaskService.class);tx=mock(PaymentCoreMapper.class);audits=mock(SysAuditLogMapper.class);var p=new PaginationProperties();p.setMaxPageSize(100);p.setBrowseLimit(100);service=new CashierService(db,access,dates,posting,tasks,records,taskService,tx,audits,new PaginationSupport(p),clock);when(access.actor()).thenReturn(new CashierAccess.Actor(7L,Set.of("STAFF")));when(dates.postingDate()).thenReturn(LocalDate.of(2026,9,24));when(audits.insert(any())).thenReturn(1);}
 @Test void initialCountCreatesRealityBaseline(){var d=Drawer.builder().id(1L).status("ACTIVE").currency("CNY").build();when(db.lockDrawer(1L)).thenReturn(d);when(db.insertShift(any())).thenAnswer(i->{((Shift)i.getArgument(0)).setId(2L);return 1;});when(db.activate(1L,2L)).thenReturn(1);when(db.shift(2L)).thenReturn(Shift.builder().id(2L).openingCount(new BigDecimal("1000.00")).build());when(db.expected(2L)).thenReturn(new BigDecimal("1000.00"));var v=service.open(1L,new Count(new BigDecimal("1000.00"),null));assertEquals(new BigDecimal("1000.00"),v.expected());verify(db,never()).insertHandover(any());}
 @Test void nextShiftHandoverUsesPreviousActualClosingNotExpected(){var d=Drawer.builder().id(1L).status("ACTIVE").currency("CNY").build();when(db.lockDrawer(1L)).thenReturn(d);when(db.insertShift(any())).thenAnswer(i->{((Shift)i.getArgument(0)).setId(3L);return 1;});when(db.activate(1L,3L)).thenReturn(1);when(db.previous(1L)).thenReturn(Shift.builder().id(2L).expectedClosing(new BigDecimal("1650.00")).closingCount(new BigDecimal("1630.00")).build());when(db.insertHandover(any())).thenReturn(1);when(db.shift(3L)).thenReturn(Shift.builder().id(3L).openingCount(new BigDecimal("1620.00")).build());when(db.expected(3L)).thenReturn(new BigDecimal("1620.00"));service.open(1L,new Count(new BigDecimal("1620.00"),null));verify(db).insertHandover(argThat(h->h.getPreviousClosingCount().compareTo(new BigDecimal("1630.00"))==0&&h.getDifferenceAmount().compareTo(new BigDecimal("-10.00"))==0));}
 @Test void unexplainedShortCreatesVarianceButNoMovementOrExpense(){var s=Shift.builder().id(2L).drawerId(1L).operatorUserId(7L).status("CLOSING").closingCount(new BigDecimal("1630.00")).build();when(db.lockShift(2L)).thenReturn(s);when(db.expected(2L)).thenReturn(new BigDecimal("1650.00"));when(db.insertVariance(any())).thenReturn(1);when(db.close(eq(2L),any(),any(),any(),any(),any())).thenReturn(1);when(db.deactivate(1L,2L)).thenReturn(1);when(db.shift(2L)).thenReturn(s);service.close(2L,new Count(new BigDecimal("1630.00"),"Unexplained till shortage"));verify(db).insertVariance(argThat(v->"SHORT".equals(v.getVarianceType())&&v.getDifferenceAmount().compareTo(new BigDecimal("-20.00"))==0));verifyNoInteractions(posting,tx);}
 @Test void transferRequestCreatesFinanceTargetTaskButNoCashMovement(){var s=Shift.builder().id(2L).drawerId(1L).operatorUserId(7L).status("ACTIVE").build();when(db.lockShift(2L)).thenReturn(s);when(db.drawer(1L)).thenReturn(Drawer.builder().id(1L).currency("CNY").build());when(tasks.insert(any())).thenAnswer(i->{((HotelTask)i.getArgument(0)).setId(8L);return 1;});when(records.insert(any())).thenReturn(1);when(db.insertTransfer(any())).thenAnswer(i->{((Transfer)i.getArgument(0)).setId(9L);return 1;});service.requestTransfer(2L,new TransferRequest(new BigDecimal("400.00"),"CASH_DROP","drop-key-123",null));verify(tasks).insert(argThat(t->"FINANCE".equals(t.getTargetRole())&&"CASH_TRANSFER:drop-key-123".equals(t.getSourceKey())));verifyNoInteractions(posting,tx);}
 @Test void financeConfirmationCompletesDomainTaskAndProducesOnePhysicalMovement(){var pending=Transfer.builder().id(9L).taskId(8L).drawerId(1L).requestedBy(7L).requestType("CASH_DROP").amount(new BigDecimal("400.00")).currency("CNY").status("PENDING").build();var done=Transfer.builder().id(9L).taskId(8L).status("COMPLETED").build();when(access.actor()).thenReturn(new CashierAccess.Actor(10L,Set.of("FINANCE")));when(db.lockTransfer(9L)).thenReturn(pending,done,done);when(db.completeTransfer(eq(9L),eq(10L),any())).thenReturn(1);when(tx.insertTransaction(any())).thenReturn(1);assertSame(done,service.confirmTransfer(9L));assertSame(done,service.confirmTransfer(9L));verify(taskService,times(1)).completeCashTransfer(8L,"Finance confirmed physical cash handover");verify(posting,times(1)).post(eq(7L),eq("OUT"),eq("CASH_DROP"),eq(new BigDecimal("400.00")),eq("CNY"),eq("CASH_TRANSFER"),eq(9L),eq("cash-transfer-9"),isNull());verify(tx,times(1)).insertTransaction(argThat(x->"INTERNAL_TRANSFER".equals(x.getDirection())));}
 @Test void cancelledTransferCancelsTaskAndCreatesNoMovement(){var pending=Transfer.builder().id(9L).taskId(8L).requestedBy(7L).status("PENDING").build();var cancelled=Transfer.builder().id(9L).taskId(8L).status("CANCELLED").build();when(db.lockTransfer(9L)).thenReturn(pending,cancelled);when(db.cancelTransfer(9L)).thenReturn(1);assertSame(cancelled,service.cancelTransfer(9L));verify(taskService).cancelCashTransfer(8L,"Cash transfer request cancelled");verifyNoInteractions(posting,tx);}
}
